	const ttlMs = Number(await db.pttl(`confirm:byUid:${uid}`));
	if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
		await UserEmail.expireValidation(uid);
		return null;
	}

	return Math.min(ttlMs, getExpiryMs());
};

